simplesect.para:
use a path of "\" to list the files in the main directory NOT "/usd/"
 DO NOT PREPEND YOUR PATHS WITH "/usd/"

\return 1 on success or PROS_ERR on failure setting errno

\b Example
@code 
void opcontrol() {
    char* test = (char*) malloc(128);
 pros::c::usd_list_files("/", test, 128);
 pros::delay(200);
 printf("s
", test); //Prints the file names in the root directory seperated by newlines
 pros::delay(100);
 pros::c::usd_list_files("/test", test, 128);
 pros::delay(200);
 printf("s
", test); //Prints the names of files in the folder named test seperated by newlines pros::delay(100); }
